Built-in ls command: list directory contents */
    if (strcmp(args[0], "ls") == 0)
    {
        if (args[1] != NULL && (strcmp(args[1], "--help") == 0 || strcmp(args[1], "-h") == 0))
        {
            display_help("ls");
            return;
        }
        const char *dir_path = (args[1] != NULL) ? args[1] : ".";
        DIR *dir = opendir(dir_path);
        if (dir == NULL)
        {
            perror("ls");
            return;
        }
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL)
        {
            /* Skip hidden files (those starting with '.') */
            if (entry->d_name[0] != '.')
            {
                printf("%s  ", entry->d_name);
            }
        }
        printf("\n");
        closedir(dir);
        return;
    }

    /* Built-in stat command: display file status */
    if (strcmp(args[0], "stat") == 0)
    {
        if (args[1] != NULL && (strcmp(args[1], "--help") == 0 || strcmp(args[1], "-h") == 0))
        {
            display_help("stat");
            return;
        }
        if (args[1] == NULL)
        {
            fprintf(stderr, "stat: missing operand\n");
            return;
        }
        struct stat st;
        if (stat(args[1], &st) != 0)
        {
            perror("stat");
            return;
        }
        printf("  File: %s\n", args[1]);
        printf("  Size: %ld\n", (long)st.st_size);
        printf("  Mode: %o\n", st.st_mode & 07777);
        printf("  Links: %ld\n", (long)st.st_nlink);
        printf("  UID: %d  GID: %d\n", st.st_uid, st.st_gid);
        printf("  Access: %s", ctime(&st.st_atime));
        printf("  Modify: %s", ctime(&st.st_mtime));
        printf("  Change: %s", ctime(&st.st_ctime));
        return;
    }

    /* Built-in cat command: concatenate and print file contents */
    if (strcmp(args[0], "cat") == 0)
    {
        if (args[1] != NULL && (strcmp(args[1], "--help") == 0 || strcmp(args[1], "-h") == 0))
        {
            display_help("cat");
            return;
        }
        if (args[1] == NULL)
        {
            fprintf(stderr, "cat: missing operand\n");
            return;
        }
        for (int i = 1; args[i] != NULL; i++)
        {
            FILE *fp = fopen(args[i], "r");
            if (fp == NULL)
            {
                perror(args[i]);
                continue;
            }
            char buf[BUFFER_SIZE];
            while (fgets(buf, sizeof(buf), fp) != NULL)
            {
                fputs(buf, stdout);
            }
            fclose(fp);
        }
        return;
    }

    /* Built-in head command: print first N lines of a file */
    if (strcmp(args[0], "head") == 0)
    {
        if (args[1] != NULL && (strcmp(args[1], "--help") == 0 || strcmp(args[1], "-h") == 0))
        {
            display_help("head");
            return;
        }
        int num_lines = 10;
        int file_arg = 1;
        if (args[1] != NULL && strcmp(args[1], "-n") == 0 && args[2] != NULL)
        {
            num_lines = atoi(args[2]);
            file_arg = 3;
        }
        if (args[file_arg] == NULL)
        {
            fprintf(stderr, "head: missing operand\n");
            return;
        }
        FILE *fp = fopen(args[file_arg], "r");
        if (fp == NULL)
        {
            perror("head");
            return;
        }
        char buf[BUFFER_SIZE];
        int count = 0;
        while (count < num_lines && fgets(buf, sizeof(buf), fp) != NULL)
        {
            fputs(buf, stdout);
            count++;
        }
        fclose(fp);
        return;
    }

    /* Built-in tail command: print last N lines of a file */
    if (strcmp(args[0], "tail") == 0)
    {
        if (args[1] != NULL && (strcmp(args[1], "--help") == 0 || strcmp(args[1], "-h") == 0))
        {
            display_help("tail");
            return;
        }
        int num_lines = 10;
        int file_arg = 1;
        if (args[1] != NULL && strcmp(args[1], "-n") == 0 && args[2] != NULL)
        {
            num_lines = atoi(args[2]);
            file_arg = 3;
        }
        if (args[file_arg] == NULL)
        {
            fprintf(stderr, "tail: missing operand\n");
            return;
        }
        FILE *fp = fopen(args[file_arg], "r");
        if (fp == NULL)
        {
            perror("tail");
            return;
        }
        char buf[BUFFER_SIZE];
        int total_lines = 0;
        while (fgets(buf, sizeof(buf), fp) != NULL)
        {
            total_lines++;
        }
        rewind(fp);
        int skip = total_lines - num_lines;
        if (skip < 0) skip = 0;
        int count = 0;
        while (fgets(buf, sizeof(buf), fp) != NULL)
        {
            if (count >= skip)
            {
                fputs(buf, stdout);
            }
            count++;
        }
        fclose(fp);
        return;
    }

    /* Built-in cp command: copy a file */
    if (strcmp(args[0], "cp") == 0)
    {
        if (args[1] != NULL && (strcmp(args[1], "--help") == 0 || strcmp(args[1], "-h") == 0))
        {
            display_help("cp");
            return;
        }
        if (args[1] == NULL || args[2] == NULL)
        {
            fprintf(stderr, "cp: missing operand\nUsage: cp <source> <destination>\n");
            return;
        }
        FILE *src = fopen(args[1], "rb");
        if (src == NULL)
        {
            perror("cp");
            return;
        }
        FILE *dst = fopen(args[2], "wb");
        if (dst == NULL)
        {
            perror("cp");
            fclose(src);
            return;
        }
        char buf[BUFFER_SIZE];
        size_t n;
        while ((n = fread(buf, 1, sizeof(buf), src)) > 0)
        {
            fwrite(buf, 1, n, dst);
        }
        fclose(src);
        fclose(dst);
        return;
    }

    /* Built-in mv command: move/rename a file */
