        {
            display_help("touch");
            return;
        }
        if (args[1] == NULL)
        {
            fprintf(stderr, "touch: missing operand\n");
            return;
        }
        for (int i = 1; args[i] != NULL; i++)
        {
            /* Try to update timestamps; if file doesn't exist, create it */
            if (utime(args[i], NULL) != 0)
