int cd_run(int argc, char **argv)
{
    struct arg_lit  *help;
    struct arg_file *dir;
    struct arg_end  *end;
    void           **argtable;

    build_cd_argtable(&help, &dir, &end, &argtable);

    int nerrors = arg_parse(argc, argv, argtable);

    if (help->count > 0)
    {
        arg_freetable(argtable, 3);
        cd_print_usage(stdout);
        return 0;
