    if (nerrors > 0)
    {
        arg_print_errors(stdout, end, "cd");
        arg_freetable(argtable, 3);
        cd_print_usage(stdout);
        return 1;
    }

    const char *target = (dir->count > 0) ? dir->filename[0] : getenv("HOME");
    if (target == NULL)
    {
        target = "/";
    }

    if (chdir(target) != 0)
    {
