/* ── run ───────────────────────────────────────────────────────────────── */

int tail_run(int argc, char **argv)
{
    struct arg_lit  *help;
    struct arg_int  *lines;
    struct arg_file *file;
    struct arg_end  *end;
    void           **argtable;

    build_tail_argtable(&help, &lines, &file, &end, &argtable);

    int nerrors = arg_parse(argc, argv, argtable);

    if (help->count > 0)
    {
        arg_freetable(argtable, 4);
        tail_print_usage(stdout);
        return 0;
    }
    if (nerrors > 0)
    {
        arg_print_errors(stdout, end, "tail");
        arg_freetable(argtable, 4);
        tail_print_usage(stdout);
        return 1;
    }

    int n = (lines->count > 0) ? lines->ival[0] : 10;

    FILE *fp = fopen(file->filename[0], "r");
    if (fp == NULL)
    {
        perror("tail");
        arg_freetable(argtable, 4);
        return 1;
    }

    /* Count total lines */
    int total = 0;
    char buf[TAIL_BUF];
    while (fgets(buf, sizeof(buf), fp) != NULL)
    {
        total++;
    }

    /* Rewind and skip to the desired window */
    rewind(fp);
    int skip = total - n;
    if (skip < 0) skip = 0;

    int cur = 0;
    while (fgets(buf, sizeof(buf), fp) != NULL)
    {
        if (cur >= skip)
        {
            fputs(buf, stdout);
        }
        cur++;
    }
    fclose(fp);

    arg_freetable(argtable, 4);
    return 0;
}

