    struct arg_file *dirs;
    struct arg_end  *end;
    void           **argtable;

    build_rmdir_argtable(&help, &parents, &dirs, &end, &argtable);

    fprintf(out, "\nUsage: rmdir ");
    arg_print_syntax(out, argtable, "\n");
