    if (nerrors > 0)
    {
        arg_print_errors(stdout, end, "cat");
        arg_freetable(argtable, 4);
        cat_print_usage(stdout);
        return 1;
    }

    int ret = 0;
    long line_num = 1;

    for (int i = 0; i < files->count; i++)
    {
        FILE *fp = fopen(files->filename[i], "r");
        if (fp == NULL)
        {
            perror(files->filename[i]);
            ret = 1;
