#define TAIL_BUF 4096

/* ── argtable builder ──────────────────────────────────────────────────── */

static void build_tail_argtable(struct arg_lit  **help,
                                 struct arg_int  **lines,
                                 struct arg_file **file,
                                 struct arg_end  **end,
                                 void           ***argtable_out)
